[
  {
    "ce_mental_state_attribution": "The workers are probably relaxed",
    "ae_explicit_nonsharing": "I don't feel any of that ease",
    "pd_harm_distress": "My stomach is knotted",
    "pd_decision_conflict": "My stomach is knotted because I was raised never to touch machinery",
    "sys_rule_justification": "I was raised never to touch machinery I don't understand",
    "pda_practical_counterfactual": "Somebody should have set the brakes on that train"
  },
  {
    "ce_mental_state_attribution": "likely trust that the line is clear",
    "ae_explicit_nonsharing": "I can't share their trust at all",
    "pd_decision_conflict": "I'm torn between leaving railway gear to railway people and not letting five people get hit",
    "pda_practical_counterfactual": "A lookout posted up the line would have spared everyone this"
  },
  {
    "ce_mental_state_attribution": "might feel sure it's all handled",
    "ae_explicit_nonsharing": "I don't share that confidence one bit",
    "pd_decision_conflict": "It sits heavy, being pulled between 'hands off what isn't yours' and five lives",
    "pda_practical_counterfactual": "someone skipped the handbrake and the wheel chocks"
  },
  {
    "ce_mental_state_attribution": "content in their routine",
    "ae_explicit_nonsharing": "None of that contentment reaches me",
    "pd_decision_conflict": "That split leaves me wrung out",
    "pda_practical_counterfactual": "radioed ahead or put a stop block behind the train"
  },
  {
    "ce_mental_state_attribution": "The workers probably aren't afraid",
    "ae_explicit_nonsharing": "I'm far from unafraid",
    "pd_decision_conflict": "feels pulled two ways: act on a machine I barely understand, or stand still",
    "pda_practical_counterfactual": "Whoever left that train should have locked it down"
  },
  {
    "ce_mental_state_attribution": "I picture those five chatting, cheerful",
    "ae_explicit_nonsharing": "I can't feel that cheer",
    "pd_decision_conflict": "I feel sick, split between trusting the system and grabbing a lever",
    "pda_practical_counterfactual": "supervisor should have made sure that train was secured"
  },
  {
    "ce_mental_state_attribution": "The workers most likely feel safe out there",
    "ae_explicit_nonsharing": "I don't share it",
    "pd_decision_conflict": "That clash leaves me anxious and a little hollow",
    "pda_practical_counterfactual": "A chained brake and a tagged switch would have kept that train still"
  },
  {
    "ce_mental_state_attribution": "men working there may be perfectly at peace",
    "ae_explicit_nonsharing": "I'm nowhere near that peace",
    "pd_decision_conflict": "the two keep grinding at me",
    "pda_practical_counterfactual": "crew ought to have set a stop block on the main line"
  },
  {
    "ce_mental_state_attribution": "The five probably feel ordinary, bored even",
    "ae_explicit_nonsharing": "I don't share that boredom",
    "pd_decision_conflict": "I feel frayed, caught between my rule of not interfering",
    "pda_practical_counterfactual": "The yard crew should have chocked the wheels"
  },
  {
    "ce_mental_state_attribution": "The workers likely feel secure",
    "ae_explicit_nonsharing": "I can't feel secure along with them",
    "pd_decision_conflict": "I'm torn",
    "pda_practical_counterfactual": "Someone should have braked that train properly before leaving it"
  }
]
